function FollowCamera({positionRef,zoom}){const target=new THREE.Vector3(),desired=new THREE.Vector3(),ahead=useRef(new THREE.Vector3()),lookTarget=useRef(new THREE.Vector3()),initialized=useRef(false);useFrame(({camera},d)=>{const p=positionRef.current;const seated=p.sitType==='chair';const facing=p.facing??Math.PI;const distance=(seated?3.8:4.35)*zoom*WORLD_SCALE;const height=(seated?1.05:1.35)*zoom*WORLD_SCALE;const worldScale=WORLD_SCALE*MAP_SIZE_SCALE;const centerZ=-10*worldScale;target.set(p.x*worldScale,(seated?.92:1.28)*worldScale,p.z*worldScale);desired.set(target.x-Math.sin(facing)*distance,target.y+height,target.z-Math.cos(facing)*distance);const cameraX=desired.x,cameraZ=desired.z-centerZ,cameraLimit=(cameraX/(17.7*worldScale))**2+(cameraZ/(16.7*worldScale))**2;if(cameraLimit>1){const correction=1/Math.sqrt(cameraLimit);desired.x=cameraX*correction;desired.z=centerZ+cameraZ*correction;}ahead.current.set(target.x+Math.sin(facing)*.42*WORLD_SCALE,target.y,target.z+Math.cos(facing)*.42*WORLD_SCALE);if(!initialized.current){camera.position.copy(desired);lookTarget.current.copy(ahead.current);initialized.current=true}else{camera.position.lerp(desired,1-Math.exp(-d*4.5));lookTarget.current.lerp(ahead.current,1-Math.exp(-d*2.2));}camera.fov=38;camera.updateProjectionMatrix();camera.lookAt(lookTarget.current)});return null}
